INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13001, 'Academic Vocabulary', 'Frayer-model vocabulary instruction with examples, non-examples, and retrieval practice.', 'Exit ticket and student explanation', '80% accuracy on two consecutive checks', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13002, 'Explicit Instruction', 'Model one worked example, complete one collaboratively, then move to independent practice.', 'Independent practice sample', 'At least 4 of 5 independent items correct', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13003, 'Metacognition', 'Students identify the error, explain why it occurred, and correct the reasoning.', 'Annotated error-analysis task', 'Student explains and corrects 3 of 4 errors', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13004, 'Targeted Reteach', 'Teacher-led small group focused on the prerequisite concept and immediate guided practice.', 'Reteach exit ticket', 'At least 80% on aligned exit ticket', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13005, 'Academic Discourse', 'Structured partner explanation using claim, evidence, and reasoning stems.', 'Teacher observation notes', 'Student gives complete explanation in 2 consecutive lessons', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13006, 'Multiple Representations', 'Connect concrete or visual representations to symbols, equations, diagrams, or text evidence.', 'Student representation task', 'Correctly connects representation and abstract form on 4 of 5 items', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13007, 'Retrieval Practice', 'Brief cumulative retrieval tasks distributed across multiple lessons.', 'Three retrieval checks', 'Average 80% across three checks', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
INSERT INTO intervention_details (intervention_id, intervention_type, strategy, evidence_to_collect, success_criterion, notes, updated_at) VALUES (13008, 'Prerequisite Skills', 'Short daily practice on the prerequisite skill followed by immediate feedback and correction.', 'Daily 5-item checks', '80% or higher for three consecutive checks', 'Seeded demo intervention; can be surfaced as a repository option.', '2026-09-21 08:00:00');
